<script setup>
import { onMounted, ref } from 'vue'
import ReportExportActions from './ReportExportActions.vue'
import { apiOrigin } from '../services/auth.js'
const props = defineProps({ session: { type: Object, required: true } })
const parts = new Intl.DateTimeFormat('en', { timeZone: 'Europe/Kyiv', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date())
const part = name => parts.find(x => x.type === name).value
const today = `${part('year')}-${part('month')}-${part('day')}`
const from = ref(today.slice(0, 7) + '-01'), to = ref(today), branch = ref(''), branches = ref([]), applied = ref(null), data = ref(null), busy = ref(false), error = ref(''), detail = ref(null), detailError = ref(''), detailBusy = ref(false), selectedId = ref(null)
const labels = { ADVANCE: 'Аванс', PAYMENT: 'Оплата', REFUND: 'Повернення' }
const money = value => Number(value || 0).toLocaleString('uk-UA', { minimumFractionDigits: 2, maximumFractionDigits: 4 })
async function api(path) { const r = await fetch(`${apiOrigin}/api/reports/cash-receipts${path}`, { headers: { Authorization: `Bearer ${props.session.token}` } }); const result = await r.json().catch(() => null); if (!r.ok) throw new Error(result?.message || `Не вдалося завантажити дані (HTTP ${r.status})`); return result }
async function load(page = 0, filters = null) { if (busy.value || detailBusy.value) return; const f = filters || applied.value; if (!f?.from || !f?.to || f.from > f.to) { error.value = 'Перевірте період.'; return } busy.value = true; error.value = ''; data.value = null; detail.value = null; selectedId.value = null; try { const q = new URLSearchParams({ from: f.from, to: f.to, page: String(page) }); if (f.branch) q.set('branch', f.branch); data.value = await api('?' + q); applied.value = { ...f } } catch (e) { error.value = e.message } finally { busy.value = false } }
function apply() { return load(0, { from: from.value, to: to.value, branch: branch.value }) }
async function open(row) { if (detailBusy.value || busy.value) return; selectedId.value = row.id; detail.value = null; detailError.value = ''; detailBusy.value = true; try { detail.value = await api('/' + row.id) } catch (e) { detailError.value = e.message } finally { detailBusy.value = false } }
onMounted(async () => { try { branches.value = await api('/branches'); await apply() } catch (e) { error.value = e.message } })
</script>
<template>
 <section class="cash-report"><h1>Рух грошей</h1><p>Фактичні надходження від клієнтів і фірм-посередників за проводками підприємства.</p>
  <form @submit.prevent="apply"><label>Від<input v-model="from" type="date" required :disabled="busy || detailBusy"></label><label>До включно<input v-model="to" type="date" required :disabled="busy || detailBusy"></label><label>Філія приймання коштів<select v-model="branch" :disabled="busy || detailBusy"><option value="">Усі філії</option><option v-for="b in branches" :key="b.id" :value="String(b.id)">{{ b.name }}</option></select></label><button :disabled="busy || detailBusy">Показати</button></form>
  <p v-if="error" role="alert">{{ error }}</p><p v-if="busy">Формування звіту…</p>
  <template v-if="data"><ReportExportActions :session="session" kind="cash" :filters="applied" :disabled="busy" /><p>{{ data.from }} — {{ data.to }} · {{ branches.find(b => String(b.id) === applied.branch)?.name || 'Усі філії' }}. Підсумки за всіма сторінками.</p>
   <div class="metrics"><article>Аванси<strong>{{ money(data.summary.advance) }} грн</strong></article><article>Оплати<strong>{{ money(data.summary.payment) }} грн</strong></article><article>Усього надійшло<strong>{{ money(data.summary.received) }} грн</strong></article><article>Повернення<strong>{{ money(data.summary.refund) }} грн</strong></article><article>Чисті надходження від клієнтів<strong>{{ money(data.summary.net) }} грн</strong></article></div>
   <details><summary>Що враховано у звіті</summary><p>Оплати й аванси — вхідні грошові проводки, повернення — вихідні. Переплата може створити два рядки: оплату рахунку та аванс; разом це одна отримана сума. Кількість рядків означає кількість проводок, не платежів.</p><p>Зарахування авансу, виставлення та об’єднання рахунків, довідкові кошти кінцевих клієнтів посередників не включаються. Погашення рахунку після його об’єднання не змінює вже записані грошові надходження.</p><p>Це не залишок каси: закупівлі, зарплати, оренда та інші виплати підприємства не враховані. Довільні коригування категорії ADJUSTMENT не трактуються автоматично як гроші. Період — за датою проводки, межі днів Europe/Kyiv. Філія — з проводки, не з замовлення.</p></details>
   <p>Проводок: {{ data.summary.count }}</p><p v-if="!data.rows.length">За цими умовами руху коштів немає.</p>
   <article v-for="row in data.rows" :key="row.id" class="cash-line"><header><strong>{{ labels[row.kind] }} · {{ money(row.signedAmount) }} грн</strong><span>{{ row.createdAt }}</span></header><p>{{ row.customerName || 'Клієнт не вказаний' }} · {{ row.branchName || 'Філія не вказана' }}</p><p v-if="row.payerName && row.payerId !== row.customerId">Платник: {{ row.payerName }}</p><p v-if="row.invoiceNo">Рахунок № {{ row.invoiceNo }}</p><p v-if="row.note">{{ row.note }}</p><small>Проводка № {{ row.id }} · {{ row.actor || 'Автор не вказаний' }}</small><div><button :disabled="busy || detailBusy" @click="open(row)">Клієнт і рахунок</button></div>
    <section v-if="selectedId === row.id" class="cash-detail"><p v-if="detailBusy">Завантаження…</p><p v-if="detailError" role="alert">{{ detailError }}</p><template v-if="detail"><h3>Дані операції</h3><p v-for="c in detail.customer" :key="c.id">Клієнт № {{ c.id }}: {{ c.name }} · {{ c.phone || 'Телефон не вказаний' }}</p><p v-if="!detail.customer.length">Пов’язаний клієнт відсутній.</p><p v-for="invoice in detail.invoice" :key="invoice.id">Рахунок № {{ invoice.invoiceNo }} · {{ money(invoice.amount) }} грн · {{ invoice.status }} · {{ invoice.lifecycle }}</p><p v-if="!detail.invoice.length">Операція не прив’язана до рахунку (наприклад, аванс на баланс клієнта).</p><p v-if="detail.entry.reference">Підстава: {{ detail.entry.reference }}</p><p v-if="detail.entry.orderNo">Замовлення № {{ detail.entry.orderNo }}</p><small>Стан рахунку показано на момент перегляду.</small></template><button :disabled="detailBusy" @click="selectedId = null">Закрити</button></section>
   </article><div class="paging"><button :disabled="busy || detailBusy || !data.page" @click="load(data.page - 1)">Назад</button><span>Сторінка {{ data.page + 1 }}</span><button :disabled="busy || detailBusy || !data.hasMore" @click="load(data.page + 1)">Далі</button></div>
  </template>
 </section>
</template>
<style scoped>
.cash-report{padding:20px;max-width:1250px;margin:auto;color:#233442;min-width:0}.cash-report form{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin:20px 0}.cash-report label{display:grid;gap:6px;flex:1 1 160px;min-width:0}.cash-report input,.cash-report select,.cash-report button{font:inherit;padding:10px;min-height:44px;border:1px solid #bdccd4;border-radius:7px;box-sizing:border-box;max-width:100%;min-width:0}.cash-report button{cursor:pointer;background:#185c63;color:#fff}.cash-report button:disabled{opacity:.5}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.metrics article{background:#eef5f6;padding:16px;border-radius:10px}.metrics strong{display:block;font-size:21px;margin-top:10px}.cash-report p{line-height:1.5}.cash-report details{margin:18px 0}.cash-report summary{cursor:pointer}.cash-line{border:1px solid #dce4e9;border-radius:10px;padding:14px;margin:12px 0;overflow-wrap:anywhere}.cash-line header{display:flex;gap:12px;flex-wrap:wrap;justify-content:space-between}.cash-line button{margin-top:10px}.cash-detail{background:#f3f7f8;padding:12px;margin-top:12px;border-radius:8px}.paging{display:flex;gap:12px;align-items:center}[role=alert]{color:#a22}@media(max-width:650px){.cash-report{padding:12px}.cash-report form button{width:100%}.metrics{grid-template-columns:1fr 1fr}.metrics article:last-child{grid-column:1/-1}}
</style>
